  //   saveAs(blob, `BaoCao_${Date.now()}.xlsx`);

  //   toast.success("Tải Excel thành công");
  // };
  const handleExportExcel = () => {
    if (reportData.length === 0) {
      toast.error("Không có dữ liệu");

      return;
    }

    const exportData = reportData.map((item) => ({
      STT: item.stt,

      "CHI NHÁNH": item.chiNhanh,

      TUYẾN: item.tuyen,

      BKS: item.bks,

      "Nội dung phản ánh": item.noiDungPhanAnh,

      "Nhân viên bị phản ánh": item.nhanVienBiPhanAnh,

      "Không vi phạm": item.khongViPham,

      "Vi phạm": item.viPham,
    }));

    // CREATE SHEET

    const worksheet = XLSX.utils.json_to_sheet(exportData);

    // WIDTH

    worksheet["!cols"] = [
      { wch: 8 },

      { wch: 18 },

      { wch: 35 },

      { wch: 16 },

      { wch: 80 },

      { wch: 30 },

      { wch: 18 },

      { wch: 18 },
    ];

    // HEADER STYLE

    const headerStyle = {
      font: {
        bold: true,

        color: {
          rgb: "FFFFFF",
        },

        sz: 12,
      },

      fill: {
        fgColor: {
          rgb: "2563EB",
        },
      },

      alignment: {
        horizontal: "center",

        vertical: "center",

        wrapText: true,
      },

      border: {
        top: {
          style: "thin",
        },

        bottom: {
          style: "thin",
        },

        left: {
          style: "thin",
        },

        right: {
          style: "thin",
        },
      },
    };

    // BODY STYLE

    const bodyStyle = {
      alignment: {
        vertical: "top",

        wrapText: true,
      },

      border: {
        top: {
          style: "thin",
        },

        bottom: {
          style: "thin",
        },

        left: {
          style: "thin",
        },

        right: {
          style: "thin",
        },
      },
    };

    // APPLY STYLE

    const range = XLSX.utils.decode_range(worksheet["!ref"]);

    for (let R = range.s.r; R <= range.e.r; ++R) {
      for (let C = range.s.c; C <= range.e.c; ++C) {
        const cellAddress = XLSX.utils.encode_cell({
          r: R,

          c: C,
        });

        if (!worksheet[cellAddress]) continue;

        // HEADER

        if (R === 0) {
          worksheet[cellAddress].s = headerStyle;
        }

        // BODY
        else {
          worksheet[cellAddress].s = bodyStyle;
        }
      }
    }

    // ROW HEIGHT

    worksheet["!rows"] = exportData.map(() => ({
      hpt: 45,
    }));

    // CREATE WORKBOOK

    const workbook = XLSX.utils.book_new();

    XLSX.utils.book_append_sheet(workbook, worksheet, "BaoCao");

    // EXPORT

    XLSX.writeFile(workbook, `BaoCao_${Date.now()}.xlsx`);

    toast.success("Tải Excel thành công");
  };
  // =========================
  // PAGINATION DATA
  // =========================

  const indexOfLastRow = currentPage * rowsPerPage;

  const indexOfFirstRow = indexOfLastRow - rowsPerPage;

  const currentRows = reportData.slice(indexOfFirstRow, indexOfLastRow);

  const totalPages = Math.ceil(reportData.length / rowsPerPage);

  return (
    <div className="report-page">
      {/* ========================= */}
      {/* HEADER */}
      {/* ========================= */}

      <div className="report-header">
        <div>
          <h1>Báo cáo hỗ trợ trích xuất</h1>

          {/* ACTIONS */}

          <div className="report-actions">
            {/* BACK */}

            <Button
              className="back-button"
              onClick={() => setCurrentPage("home")}
            >
              ← Quay lại
            </Button>

            {/* EXPORT */}

            <Button className="export-button" onClick={handleExportExcel}>
              ⬇ Tải Excel
            </Button>
          </div>
        </div>

        {/* TOTAL */}

        <p>
          Tổng số phản ánh:
          <span>{reportData.length}</span>
        </p>
      </div>

      {/* ========================= */}
      {/* FILTER INFO */}
      {/* ========================= */}

      <div className="report-filter-info">
        {/* DATE */}

        <div className="report-info-card">
          <div className="info-header">
            <div className="info-title">📅 Khoảng thời gian</div>

            <button className="copy-button" onClick={handleCopyDate}>
              Copy
            </button>
          </div>

          <div className="info-content">
            Từ ngày {formatDate(startDate)} đến ngày {formatDate(endDate)}
          </div>
        </div>

        {/* EMPLOYEE */}

        <div className="report-info-card">
          <div className="info-header">
            <div className="info-title">👤 Nhân viên</div>

            <button className="copy-button" onClick={handleCopyEmployees}>
              Copy
            </button>
          </div>

          <div className="info-content">{employeeInput}</div>
        </div>
      </div>

      {/* ========================= */}
      {/* TABLE */}
      {/* ========================= */}

      <div className="report-table-wrapper">
        <table className="report-table">
          <thead>
            <tr>
              <th>STT</th>

              <th>CHI NHÁNH</th>

              <th>TUYẾN</th>

              <th>BKS</th>

              <th>Nội dung phản ánh</th>

              <th>Nhân viên bị phản ánh</th>

              <th>Không vi phạm</th>

              <th>Vi phạm</th>
            </tr>
          </thead>

          <tbody>
            {currentRows.map((item, index) => (
              <tr key={index}>
                <td>{item.stt}</td>

                <td>{item.chiNhanh}</td>

                <td>{item.tuyen}</td>

                <td>{item.bks}</td>

                <td>{item.noiDungPhanAnh}</td>

                <td>{item.nhanVienBiPhanAnh}</td>

                <td>{item.khongViPham}</td>

                <td>{item.viPham}</td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* ========================= */}
        {/* PAGINATION */}
        {/* ========================= */}

        {reportData.length > 0 && (
          <div className="pagination">
            {/* LEFT */}

            <div className="pagination-left">
              <span>Hiển thị</span>

              <select
                value={rowsPerPage}
                onChange={(e) => {
                  setRowsPerPage(Number(e.target.value));

                  setPage(1);
                }}
              >
                <option value={20}>20</option>

                <option value={50}>50</option>

                <option value={100}>100</option>
              </select>

              <span>dòng</span>
            </div>

            {/* RIGHT */}

            <div className="pagination-pages">
              {Array.from(
                {
                  length: totalPages,
                },
                (_, i) => i + 1,
              ).map((page) => (
                <button
                  key={page}
                  className={
                    currentPage === page ? "page-btn active" : "page-btn"
                  }
                  onClick={() => setPage(page)}
                >
                  {page}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
